import {
  ArrowLeft,
  ArrowRight,
  BookOpenText,
  CheckCircle2,
  Layers3,
  Search,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { cn } from "../../lib/cn";
import { useKnowledge, knowledgeMasteryByBook } from "../../store/knowledge";
import SpotlightCard from "../reactbits/vendor/SpotlightCard/SpotlightCard";
import {
  KNOWLEDGE_BOOKS,
  KNOWLEDGE_CATEGORIES,
  knowledgeCategoryById,
  nodesForBook,
} from "./knowledgeCatalog";
import "./knowledge.css";

export function KnowledgeLibraryPage() {
  const navigate = useNavigate();
  const { categoryId } = useParams();
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const attempts = useKnowledge((state) => state.attempts);
  const [query, setQuery] = useState("");

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const category = knowledgeCategoryById(categoryId);
  const books = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    return KNOWLEDGE_BOOKS.filter((book) => {
      if (categoryId && book.categoryId !== categoryId) return false;
      if (!normalized) return true;
      return `${book.title} ${book.zhTitle} ${book.author}`
        .toLowerCase()
        .includes(normalized);
    });
  }, [categoryId, query]);

  const recentBooks = useMemo(() => {
    const lastAttemptByBook = new Map<string, number>();
    attempts.forEach((attempt) => {
      const at = new Date(attempt.at).getTime();
      lastAttemptByBook.set(
        attempt.bookId,
        Math.max(lastAttemptByBook.get(attempt.bookId) ?? 0, at),
      );
    });
    return [...lastAttemptByBook.entries()]
      .sort((left, right) => right[1] - left[1])
      .slice(0, 3)
      .map(([bookId]) => KNOWLEDGE_BOOKS.find((book) => book.id === bookId))
      .filter((book) => book !== undefined);
  }, [attempts]);

  return (
    <main className="knowledge-library">
      <header className="knowledge-library__header">
        <button
          type="button"
          className="knowledge-icon-button"
          onClick={() => navigate(category ? "/library" : "/shelf")}
          aria-label={category ? "返回全部知识分类" : "返回书房"}
        >
          <ArrowLeft size={18} />
        </button>
        <div>
          <span className="knowledge-eyebrow">
            Library · Knowledge collection
          </span>
          <h1>{category?.title ?? "Knowledge Library"}</h1>
          <p>
            {category?.description ??
              "六类主书，把讲义、笔记、赏析、课后题和错题收进同一套知识地图。"}
          </p>
        </div>
        <span className="knowledge-library__count">
          <Layers3 size={15} />
          {books.length} books
        </span>
      </header>

      {!category ? (
        <section className="knowledge-categories" aria-label="知识分类">
          {KNOWLEDGE_CATEGORIES.map((item, index) => {
            const ownedBooks = KNOWLEDGE_BOOKS.filter(
              (book) => book.categoryId === item.id,
            );
            const nodeCount = ownedBooks.reduce(
              (sum, book) => sum + nodesForBook(book).length,
              0,
            );
            return (
              <SpotlightCard
                key={item.id}
                className="knowledge-category-card"
                as="button"
                spotlightColor="rgba(47, 135, 171, 0.13)"
                style={
                  {
                    "--knowledge-accent": item.accent,
                  } as React.CSSProperties
                }
                onClick={() => navigate(`/library/${item.id}`)}
              >
                <span className="knowledge-category-card__number">
                  {String(index + 1).padStart(2, "0")}
                </span>
                <span>
                  <small>{item.titleZh}</small>
                  <strong>{item.title}</strong>
                </span>
                <p>{item.description}</p>
                <footer>
                  <em>{nodeCount} knowledge points</em>
                  <ArrowRight size={16} />
                </footer>
              </SpotlightCard>
            );
          })}
        </section>
      ) : null}

      <section className="knowledge-library__toolbar">
        <label>
          <Search size={16} />
          <input
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="搜索主书或分类…"
          />
        </label>
        {category ? (
          <div className="knowledge-library__tabs">
            {KNOWLEDGE_CATEGORIES.map((item) => (
              <button
                type="button"
                key={item.id}
                className={cn(item.id === category.id && "is-active")}
                onClick={() => navigate(`/library/${item.id}`)}
              >
                {item.titleZh}
              </button>
            ))}
          </div>
        ) : null}
      </section>

      <section className="knowledge-books" aria-label="主书列表">
        {books.map((book) => {
          const nodes = nodesForBook(book);
          const mastered = cards.filter(
            (card) =>
              card.bookId === book.id && card.mastery === "mastered",
          ).length;
          const progress = knowledgeMasteryByBook(cards, book.id);
          return (
            <SpotlightCard
              as="article"
              key={book.id}
              className="knowledge-book-card"
              spotlightColor="rgba(47, 135, 171, 0.1)"
              style={
                {
                  "--book-accent": book.accent,
                  "--book-secondary": book.secondary,
                } as React.CSSProperties
              }
            >
              <button
                type="button"
                className="knowledge-book-card__cover"
                onClick={() => navigate(`/book/${book.id}`)}
                aria-label={`打开 ${book.title}`}
              >
                <small>{book.categoryId}</small>
                <strong>{book.title}</strong>
                <em>{book.zhTitle}</em>
              </button>
              <div className="knowledge-book-card__copy">
                <span className="knowledge-eyebrow">Primary volume</span>
                <h2>{book.title}</h2>
                <p>{book.summaryZh}</p>
                <div className="knowledge-book-card__sources">
                  {book.sources.slice(0, 3).map((source) => (
                    <span key={source}>{source}</span>
                  ))}
                </div>
                <div className="knowledge-book-card__stats">
                  <span>
                    <strong>{book.modules.length}</strong>
                    modules
                  </span>
                  <span>
                    <strong>{nodes.length}</strong>
                    nodes
                  </span>
                  <span>
                    <strong>{mastered}</strong>
                    mastered
                  </span>
                </div>
                <div className="knowledge-book-card__progress">
                  <i style={{ width: `${progress}%` }} />
                </div>
                <button
                  type="button"
                  onClick={() => navigate(`/book/${book.id}`)}
                >
                  <BookOpenText size={15} />
                  Continue learning
                  <ArrowRight size={15} />
                </button>
              </div>
            </SpotlightCard>
          );
        })}
        {books.length === 0 ? (
          <div className="knowledge-empty">
            <CheckCircle2 size={22} />
            <strong>没有匹配的主书</strong>
            <p>换一个关键词，或返回六类知识分类。</p>
          </div>
        ) : null}
      </section>

      {!category && recentBooks.length > 0 ? (
        <section className="knowledge-recent">
          <header>
            <span className="knowledge-eyebrow">Recently practiced</span>
            <h2>继续学习</h2>
          </header>
          <div>
            {recentBooks.map((book) => (
              <button
                type="button"
                key={book.id}
                onClick={() => navigate(`/book/${book.id}`)}
              >
                <span style={{ background: book.accent }} />
                <strong>{book.title}</strong>
                <small>{book.zhTitle}</small>
                <ArrowRight size={15} />
              </button>
            ))}
          </div>
        </section>
      ) : null}
    </main>
  );
}
